function updateRenfortType(){
  const type=document.querySelector('input[name="renfort-type"]:checked')?.value;
  const lblC=document.getElementById('lbl-renfort-complet');
  const lblP=document.getElementById('lbl-renfort-personnel');
  if(lblC)lblC.style.borderColor=type==='complet'?'#7C3AED':'var(--brd)';
  if(lblC)lblC.style.background=type==='complet'?'#F5F3FF':'';
  if(lblP)lblP.style.borderColor=type==='personnel'?'#7C3AED':'var(--brd)';
  if(lblP)lblP.style.background=type==='personnel'?'#F5F3FF':'';
}

function envoyerRenfort(ivId){
  const iv=IVS.find(v=>v.id===ivId);if(!iv)return;
  const checkedType=document.querySelector('input[name="renfort-type"]:checked')?.value;
  const hiddenType=document.querySelector('input[type="hidden"][name="renfort-type"]')?.value;
  const type=checkedType||hiddenType||'complet';
  const note=document.getElementById('renfort-note')?.value.trim()||'';
  const destinataires=Array.from(document.querySelectorAll('.renfort-cas-chk:checked')).map(function(c){return c.value;});
  if(!destinataires.length){showToast('S\u00e9lectionne au moins une caserne.','warn');return;}
  const heure=getHHMM(N());
  const caserneSource=CC();
  const renfortId='renfort_'+Date.now();
  const renfort={
    id:renfortId,
    ivId:ivId,
    ivNature:iv.n,
    ivCommune:iv.com,
    ivAdresse:iv.adr||'',
    type:type,
    hDemande:heure,
    hDebut:null,
    hFin:null,
    caserneSource:CURRENT_CASERNE_ID,
    caserneSourceNom:caserneSource?caserneSource.nom:'',
    note:note,
    statut:'en-attente', // en-attente | accepte | en-cours | termine | refuse
    equipageRendort:null,
  };
  // Envoyer à chaque caserne destinataire
  const _renfortRecords=[];
  destinataires.forEach(function(cid){
    if(!CASERNE_DATA[cid])initCaserneData(cid);
    if(!CASERNE_DATA[cid].renforts)CASERNE_DATA[cid].renforts=[];
    const renfortDest={...renfort,caserneDest:cid};
    CASERNE_DATA[cid].renforts.push(renfortDest);
    // En mode records : préparer l'enregistrement à pousser vers la caserne destinataire
    if(typeof USE_RECORDS!=='undefined'&&USE_RECORDS&&typeof _rcId==='function'){
      _renfortRecords.push({id:_rcId(cid,'renfort',renfortDest.id),caserne:cid,type:'renfort',data:renfortDest,deleted:false});
    }
  });
  // Pousser explicitement ces demandes vers Supabase (sinon elles ne partent pas,
  // car la synchro ne pousse normalement que la caserne active de l'émetteur)
  if(_renfortRecords.length&&typeof _rcPushRecords==='function'){_rcPushRecords(_renfortRecords);}
  // Garder trace dans l'intervention
  if(!iv._renforts)iv._renforts=[];
  iv._renforts.push({id:renfortId,type,destinataires,hDemande:heure,note,statut:'en-attente'});
  iv.tl.push({s:'renfort',h:getH(N()),who:CU.l,
    note:'Demande de renfort '+( type==='complet'?'complet (camion+\u00e9quipage)':'personnel')
      +' vers : '+destinataires.map(function(cid){const c=CASERNES.find(x=>x.id===cid);return c?c.nom:cid;}).join(', ')});
  saveData();cM();
  setTimeout(function(){oM(ivId);},80);
  showToast('Demande de renfort envoy\u00e9e \u00e0 '+destinataires.length+' caserne(s)','success');
}

// Accepter / refuser un renfort (caserne destinataire)
function repondreRenfort(cid,renfortId,reponse){
  const d=CASERNE_DATA[cid];if(!d)return;
  const r=d.renforts.find(function(x){return x.id===renfortId;});if(!r)return;
  r.statut=reponse;
  r.hReponse=getHHMM(N());
  r.reponduPar=CU?CU.l:'';
  // Mettre à jour le statut dans l'intervention source
  const dSource=CASERNE_DATA[r.caserneSource];
  if(dSource){
    const ivSrc=(dSource.ivs||[]).find(function(iv){return iv.id===r.ivId;});
    if(ivSrc&&ivSrc._renforts){
      const rSrc=ivSrc._renforts.find(function(x){return x.id===renfortId;});
      if(rSrc){
        rSrc.statut=reponse;
        const cas=CASERNES.find(function(c){return c.id===cid;});
        if(!ivSrc.tl)ivSrc.tl=[];
        ivSrc.tl.push({s:'renfort',h:getH(N()),who:CU?CU.l:'',
          note:'Renfort '+(reponse==='accepte'?'accept\u00e9':'refus\u00e9')+' par '+(cas?cas.nom:cid)});
      }
    }
  }
  saveData(true); // push immédiat : réponse renfort partagée entre casernes
  rI();
  showToast('Renfort '+(reponse==='accepte'?'accept\u00e9 \u2014 l\u00e9quipage va d\u00e9partir':'refus\u00e9'),'success');
  // Si accepté, ouvrir la modale d'équipage renfort
  if(reponse==='accepte')setTimeout(function(){showRenfortEquipageModal(cid,renfortId);},200);
}

function showRenfortEquipageModal(cid,renfortId){
  const r=CASERNE_DATA[cid]?.renforts?.find(function(x){return x.id===renfortId;});if(!r)return;
  const heure=getHHMM(N());
  r.hDebut=heure;
  // Construire sélecteurs selon le type
  const isComplet=r.type==='complet';
  const enginOpts=[''].concat(ASTR_CONFIG.engins||[]).map(function(e){return '<option value="'+e+'">'+(e||'\u2014 Aucun \u2014')+'</option>';}).join('');
  const enginBlock=isComplet?'<div class="fg"><div class="fgl">Engin engag\u00e9</div><select class="fi" id="renfort-engin">'+enginOpts+'</select></div>':'';

  document.getElementById('mt').textContent='Composition de l\u2019\u00e9quipage de renfort';
  document.getElementById('mi').textContent=r.ivNature+' \u2014 '+r.ivCommune+' ('+(isComplet?'Renfort complet':'Renfort personnel')+')';
  document.getElementById('mb').innerHTML=
    '<div>'
    +'<div style="background:#EDE9FE;border-radius:8px;padding:8px 12px;margin-bottom:12px;font-size:12px;color:#5B21B6;">'
    +'Caserne demandeuse : <strong>'+r.caserneSourceNom+'</strong> \u2014 D\u00e9part : <strong>'+heure+'</strong></div>'
    +enginBlock
    +'<div style="font-size:12px;font-weight:600;margin-bottom:8px;">\u00c9quipage :</div>'
    +'<div id="renfort-equip-rows">'
    +buildRenfortEquipRow(0,null,'Chef d\u2019agr\u00e8s')
    +buildRenfortEquipRow(1,null,'Conducteur')
    +(isComplet?buildRenfortEquipRow(2,null,'\u00c9quipier'):'')
    +'</div>'
    +'<div class="brow" style="margin-top:10px;">'
    +'<button class="btn sm" style="background:#7C3AED;color:#fff;" onclick="confirmerRenfortEquipage(\''+cid+'\',\''+renfortId+'\')">&#x1F692; Confirmer le d\u00e9part</button>'
    +'<button class="btn sm" onclick="cM()">Retour</button>'
    +'</div></div>';
  document.getElementById('mo').style.display='flex';
}

function buildRenfortEquipRow(idx,login,role){
  const opts='<option value="">\u2014 Aucun \u2014</option>'
    +sortByGradeThenName(USERS).map(function(u){
      return '<option value="'+u.l+'"'+(u.l===login?' selected':'')+'>'+fullName(u)+' ('+gradeAbbr(u.grade)+')</option>';
    }).join('');
  return '<div style="margin-bottom:6px;display:grid;grid-template-columns:120px 1fr;gap:8px;align-items:center;">'
    +'<span style="font-size:11px;font-weight:600;color:var(--t2);">'+role+'</span>'
    +'<select class="fi" id="renfort-eq-'+idx+'">'+opts+'</select></div>';
}

function confirmerRenfortEquipage(cid,renfortId){
  const r=CASERNE_DATA[cid]?.renforts?.find(function(x){return x.id===renfortId;});if(!r)return;
  const engin=document.getElementById('renfort-engin')?.value||'';
  const equip=[];
  [0,1,2,3].forEach(function(i){
    const sel=document.getElementById('renfort-eq-'+i);
    const roles=['Chef d\u2019agr\u00e8s','Conducteur','\u00c9quipier','\u00c9quipier 2'];
    if(sel&&sel.value){
      const u=USERS.find(function(x){return x.l===sel.value;})||{};
      equip.push({role:roles[i],login:sel.value,hDebut:getHHMM(N()),nom:u.nom||'',prenom:u.prenom||'',grade:u.grade||''});
    }
  });
  r.equipageRenfort=equip;
  r.enginRenfort=engin;
  r.statut='en-cours';
  r.hDebut=getHHMM(N());

  // ── Créer l'IV locale dans la caserne renforcée ──
  const dSrc=CASERNE_DATA[r.caserneSource];
  const ivSrc=dSrc?(dSrc.ivs||[]).find(function(iv){return iv.id===r.ivId;}):null;
  const casSrc=CASERNES.find(function(c){return c.id===r.caserneSource;});
  if(!CASERNE_DATA[cid].ivs)CASERNE_DATA[cid].ivs=[];
  // Éviter les doublons
  const ivId=r.ivId+'_renfort_'+cid;
  if(!CASERNE_DATA[cid].ivs.find(function(iv){return iv.id===ivId;})){
    CASERNE_DATA[cid].ivs.push({
      id:ivId,
      _isRenfort:true,
      _renfortId:renfortId,
      _caserneSource:r.caserneSource,
      _caserneSourceNom:casSrc?casSrc.nom:r.caserneSource,
      _ivSourceId:r.ivId,
      h:ivSrc?ivSrc.h:getH(N()),
      n:r.ivNature,
      com:r.ivCommune,
      adr:r.ivAdresse||'',
      addr:r.ivAdresse||r.ivCommune||'',
      s:'en-cours',
      agr:equip.length?equip[0].login:(CU?CU.l:''),
      _hDebut:r.hDebut,
      _hFin:null,
      _equipage1:equip,
      _personnel:equip.map(function(e){return e.login;}),
      eng:engin,
      tl:[{s:'en-cours',h:getH(N()),who:CU?CU.l:'',note:'Renfort depuis '+(casSrc?casSrc.nom:r.caserneSource)}],
      req:ivSrc?ivSrc.req:'',
      tel:ivSrc?ivSrc.tel:'',
      op:CU?CU.l:'',
    });
  }

  // Intégrer dans l'intervention source
  if(ivSrc){
    if(r.type==='personnel'){
      if(!ivSrc._equipage1)ivSrc._equipage1=[];
      equip.forEach(function(e){ivSrc._equipage1.push({...e,renfort:true,caserneRenfort:cid});});
    } else {
      if(!ivSrc._releves)ivSrc._releves=[];
      ivSrc._releves.push({
        hReleve:r.hDebut,isRenfort:true,caserneRenfort:cid,enginRenfort:engin,
        ancienEquipage:[],
        nouvelEquipage:equip.map(function(e){return{...e,hDebut:r.hDebut};})
      });
    }
    if(!ivSrc.tl)ivSrc.tl=[];
    const cas=CASERNES.find(function(c){return c.id===cid;});
    ivSrc.tl.push({s:'renfort',h:getH(N()),who:CU?CU.l:'',
      note:'Renfort '+(r.type==='complet'?'complet':'personnel')+' de '+(cas?cas.nom:cid)+' en route'});
  }

  saveData(true); // push immédiat : état renfort partagé entre casernes
  // Recharger le contexte si on est sur la caserne renforcée
  if(CURRENT_CASERNE_ID===cid){syncCaserneContext();}
  cM();rI();
  showToast('\u00c9quipage de renfort en route !','success');
}

function cloturerRenfort(cid,renfortId){
  const r=CASERNE_DATA[cid]?.renforts?.find(function(x){return x.id===renfortId;});if(!r)return;
  r.statut='termine';
  r.hFin=getHHMM(N());
  // Clôturer aussi l'IV de renfort locale (sinon elle reste affichée "en-cours")
  const ivLocale=(CASERNE_DATA[cid]?.ivs||[]).find(function(iv){return iv._renfortId===renfortId;});
  if(ivLocale){
    ivLocale.s='terminee';
    ivLocale._hFin=r.hFin;
    if(!ivLocale.tl)ivLocale.tl=[];
    ivLocale.tl.push({s:'terminee',h:getH(N()),who:CU?CU.l:'',note:'Clôture renfort'});
  }
  saveData(true);cM();rI(); // push immédiat : changement de statut partagé ; fermeture du modal
  showToast('Renfort cl\u00f4tur\u00e9 \u00e0 '+r.hFin,'success');
}

// Annulation ciblée d'un renfort pour une seule UT (seulement si pas encore répondu)
function annulerRenfortUT(ivId,renfortId,cid){
  const ivSrc=IVS.find(function(iv){return iv.id===ivId;});if(!ivSrc)return;
  const rSrc=ivSrc._renforts?.find(function(x){return x.id===renfortId;});if(!rSrc)return;
  // Vérifier que l'UT n'a pas encore répondu
  const rDest=(CASERNE_DATA[cid]?.renforts||[]).find(function(x){return x.id===renfortId;});
  if(rDest&&rDest.statut!=='en-attente'){
    showToast('Cette UT a d\u00e9j\u00e0 r\u00e9pondu \u2014 annulation impossible.','warn');return;
  }
  // Annuler pour cette caserne
  if(rDest)rDest.statut='annule';
  // Supprimer l'IV locale renfort si elle existe
  if(CASERNE_DATA[cid]?.ivs){
    CASERNE_DATA[cid].ivs=CASERNE_DATA[cid].ivs.filter(function(iv){return iv._renfortId!==renfortId;});
  }
  // Si toutes les casernes sont annulées/terminées/refusées → marquer la demande globale
  const toutesTerminees=rSrc.destinataires.every(function(destCid){
    const rd=(CASERNE_DATA[destCid]?.renforts||[]).find(function(x){return x.id===renfortId;});
    return !rd||['annule','termine','refuse'].includes(rd.statut);
  });
  if(toutesTerminees)rSrc.statut='annule';
  const cas=CASERNES.find(function(c){return c.id===cid;});
  ivSrc.tl.push({s:'renfort',h:getH(N()),who:CU?CU.l:'',note:'Annulation renfort pour '+(cas?cas.nom:cid)});
  saveData(true);setTimeout(function(){oM(ivId);},80); // push immédiat
  showToast('Demande annul\u00e9e pour '+(cas?cas.nom:cid),'success');
}


// === MODULE: autorisation.js ===
// ═══════════════════════════════════════
// AUTORISATION & ATTESTATION
// ═══════════════════════════════════════
const LOGO_IMG_B64 = '';
const AUTORISATION_DOCX_B64 = '';

let _autorisationData = {};

function showAutorisationModal(ivId) {
  const iv = IVS.find(function(v) { return v.id === ivId; });
  if (!iv) return;
  const today = new Date();
  const dateDefault = today.getFullYear() + '-' + pad(today.getMonth()+1) + '-' + pad(today.getDate());
  const saved = _autorisationData[ivId] || {};
  if (iv._autorisationData) Object.assign(saved, iv._autorisationData);
  const typeOpts = ['Propri\u00e9taire','Locataire','Autre'].map(function(t) {
    return '<option value="' + t + '"' + (saved.demandeurType === t ? ' selected' : '') + '>' + t + '</option>';
  }).join('');
  const TRAV = ['D\u00e9pose d\u2019une antenne','D\u00e9montage de t\u00f4les','D\u00e9pose de tuiles','D\u00e9coupe d\u2019un panneau','R\u00e9alisation d\u2019une trou\u00e9e dans un mur ou une chemin\u00e9e'];
  const travauxHtml = TRAV.map(function(t) {
    const chk = saved.travaux && saved.travaux.includes(t);
    return '<label style="display:flex;align-items:center;gap:8px;font-size:12px;cursor:pointer;">'
      + '<input type="checkbox" name="aut-trav" value="' + t + '" ' + (chk ? 'checked' : '') + ' style="width:15px;height:15px;accent-color:var(--red);">'
      + '<span>' + t + '</span></label>';
  }).join('');
  document.getElementById('mt').textContent = 'Autorisation & Attestation';
  document.getElementById('mi').textContent = iv.n + ' \u2014 ' + iv.com;
  document.getElementById('mb').innerHTML =
    '<div style="max-height:70vh;overflow-y:auto;padding:4px 0;">'
    + '<div style="background:#FEF0E7;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:12px;color:#854F0B;">Remplissez le formulaire puis g\u00e9n\u00e9rez l\'aper\u00e7u PDF ou envoyez l\'attestation par mail.</div>'
    + '<div class="fg"><div class="fgl">Qualit\u00e9 du demandeur</div>'
    + '<select class="fi" id="aut-type" onchange="autToggleAutre()">' + typeOpts + '</select></div>'
    + '<div id="aut-autre-bloc" style="display:none;" class="fg"><div class="fgl">Pr\u00e9ciser</div>'
    + '<input class="fi" id="aut-autre-txt" type="text" value="' + (saved.autreTexte || '') + '"/></div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<div class="fg"><div class="fgl">Nom</div><input class="fi" id="aut-nom" type="text" value="' + (saved.nom || '') + '"/></div>'
    + '<div class="fg"><div class="fgl">Pr\u00e9nom</div><input class="fi" id="aut-prenom" type="text" value="' + (saved.prenom || '') + '"/></div></div>'
    + '<div class="fg"><div class="fgl">Adresse</div><input class="fi" id="aut-adresse" type="text" value="' + (saved.adresse || iv.adr || iv.addr || '') + '"/></div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<div class="fg"><div class="fgl">Commune</div><input class="fi" id="aut-commune" type="text" value="' + (saved.commune || iv.com || '') + '"/></div>'
    + '<div class="fg"><div class="fgl">Date intervention</div><input class="fi" id="aut-date" type="date" value="' + (saved.date || dateDefault) + '"/></div></div>'
    + '<div class="fg"><div class="fgl">Objet</div><input class="fi" id="aut-objet" type="text" value="' + (saved.objet || iv.n || '') + '"/></div>'
    + '<div class="fg"><div class="fgl">Nature r\u00e9alis\u00e9e</div>'
    + '<textarea class="fi" id="aut-nature" rows="2" style="resize:vertical;">' + (saved.nature || iv.n || '') + '</textarea></div>'
    + '<div class="fg"><div class="fgl" style="margin-bottom:6px;">Travaux (cocher = effectu\u00e9)</div>'
    + '<div style="display:flex;flex-direction:column;gap:4px;">' + travauxHtml
    + '<label style="display:flex;align-items:center;gap:8px;font-size:12px;">'
    + '<input type="checkbox" id="aut-tautre" ' + (saved.travauxAutreChk ? 'checked' : '') + ' style="width:15px;height:15px;accent-color:var(--red);">'
    + '<input class="fi" id="aut-tautre-txt" type="text" placeholder="Autre (pr\u00e9ciser)..." style="flex:1;" value="' + (saved.travauxAutreTxt || '') + '"/></label>'
    + '</div></div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<div class="fg"><div class="fgl">Date de signature</div><input class="fi" id="aut-sig-date" type="date" value="' + (saved.sigDate || dateDefault) + '"/></div>'
    + '<div class="fg"><div class="fgl">Lieu de signature</div><input class="fi" id="aut-sig-lieu" type="text" value="' + (saved.sigLieu || iv.com || '') + '"/></div></div>'
    + '<div class="fg"><div class="fgl" style="margin-bottom:6px;">Signature du demandeur</div>'
    + '<div style="border:2px solid var(--brd);border-radius:10px;background:#fff;overflow:hidden;position:relative;">'
    + '<canvas id="aut-signature" width="600" height="150" style="width:100%;height:150px;touch-action:none;cursor:crosshair;display:block;"></canvas>'
    + '<button type="button" onclick="clearSignature()" style="position:absolute;top:6px;right:6px;background:rgba(255,255,255,.9);border:1px solid var(--brd);border-radius:6px;padding:2px 8px;font-size:11px;cursor:pointer;">Effacer</button>'
    + '<div id="aut-sig-hint" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:12px;color:#ccc;pointer-events:none;">Signer ici</div>'
    + '</div></div>'
    + '<div class="brow" style="margin-top:12px;flex-wrap:wrap;gap:6px;">'
    + '<button class="btn sm" style="background:#185FA5;color:#fff;" onclick="previewAutorisationPDF(\'' + ivId + '\',\'autorisation\')">&#x1F4CB; Autorisation</button>'
    + '<button class="btn sm" style="background:#E67E22;color:#fff;" onclick="envoyerAttestationMail(\'' + ivId + '\')">&#x2709;&#xFE0F; Envoyer attestation</button>'
    + '<button class="btn sm" onclick="saveAutorisationData(\'' + ivId + '\')">&#x1F4BE; Sauvegarder</button>'
    + '</div></div>';
  document.getElementById('mo').style.display = 'flex';
  setTimeout(function() {
    autToggleAutre();
    initSignatureCanvas();
    if (saved.signature && _sigCanvas && _sigCtx) {
      const img = new Image();
      img.onload = function() { _sigCtx.drawImage(img, 0, 0); _sigHasSig = true; const h = document.getElementById('aut-sig-hint'); if (h) h.style.display = 'none'; };
      img.src = saved.signature;
    }
  }, 100);
}

function autToggleAutre() {
  const el = document.getElementById('aut-type');
  const t = el ? el.value : '';
  const b = document.getElementById('aut-autre-bloc');
  if (b) b.style.display = t === 'Autre' ? 'block' : 'none';
}

function saveAutorisationData(ivId) {
  const travaux = Array.from(document.querySelectorAll('input[name="aut-trav"]:checked')).map(function(cb) { return cb.value; });
  const sig = (_sigCanvas && _sigHasSig) ? _sigCanvas.toDataURL('image/png') : null;
  const d = {
    demandeurType: (document.getElementById('aut-type') || {}).value || '',
    autreTexte: (document.getElementById('aut-autre-txt') || {}).value || '',
    nom: (document.getElementById('aut-nom') || {}).value || '',
    prenom: (document.getElementById('aut-prenom') || {}).value || '',
    adresse: (document.getElementById('aut-adresse') || {}).value || '',
    commune: (document.getElementById('aut-commune') || {}).value || '',
    date: (document.getElementById('aut-date') || {}).value || '',
    objet: (document.getElementById('aut-objet') || {}).value || '',
    nature: (document.getElementById('aut-nature') || {}).value || '',
    sigDate: (document.getElementById('aut-sig-date') || {}).value || '',
    sigLieu: (document.getElementById('aut-sig-lieu') || {}).value || '',
    travaux: travaux,
    travauxAutreChk: !!(document.getElementById('aut-tautre') || {}).checked,
    travauxAutreTxt: (document.getElementById('aut-tautre-txt') || {}).value || '',
    signature: sig
  };
  _autorisationData[ivId] = d;
  const iv = IVS.find(function(v) { return v.id === ivId; });
  if (iv) iv._autorisationData = d;
  saveData();
  showToast('Formulaire sauvegard\u00e9', 'success');
}

let _sigCanvas = null, _sigCtx = null, _sigDrawing = false, _sigHasSig = false;
function initSignatureCanvas() {
  _sigCanvas = document.getElementById('aut-signature');
  if (!_sigCanvas) return;
  _sigCtx = _sigCanvas.getContext('2d');
  _sigCtx.strokeStyle = '#1a1a2e'; _sigCtx.lineWidth = 2.5; _sigCtx.lineCap = 'round'; _sigCtx.lineJoin = 'round';
  function getPos(e) {
    const r = _sigCanvas.getBoundingClientRect(), sx = _sigCanvas.width/r.width, sy = _sigCanvas.height/r.height;
    if (e.touches) return {x:(e.touches[0].clientX-r.left)*sx,y:(e.touches[0].clientY-r.top)*sy};
    return {x:(e.clientX-r.left)*sx,y:(e.clientY-r.top)*sy};
  }
  function start(e){_sigDrawing=true;_sigHasSig=true;const h=document.getElementById('aut-sig-hint');if(h)h.style.display='none';const p=getPos(e);_sigCtx.beginPath();_sigCtx.moveTo(p.x,p.y);e.preventDefault();}
  function draw(e){if(!_sigDrawing)return;const p=getPos(e);_sigCtx.lineTo(p.x,p.y);_sigCtx.stroke();e.preventDefault();}
  function stop(){_sigDrawing=false;}
  _sigCanvas.addEventListener('mousedown',start);_sigCanvas.addEventListener('mousemove',draw);
  _sigCanvas.addEventListener('mouseup',stop);_sigCanvas.addEventListener('mouseleave',stop);
  _sigCanvas.addEventListener('touchstart',start,{passive:false});_sigCanvas.addEventListener('touchmove',draw,{passive:false});
  _sigCanvas.addEventListener('touchend',stop);
}
function clearSignature(){
  if(!_sigCtx||!_sigCanvas)return;
  _sigCtx.clearRect(0,0,_sigCanvas.width,_sigCanvas.height);_sigHasSig=false;
  const h=document.getElementById('aut-sig-hint');if(h)h.style.display='block';
}

function previewAutorisationPDF(ivId, docType) {
  saveAutorisationData(ivId);
  const iv = IVS.find(function(v){return v.id===ivId;});if(!iv)return;
  const cas = CC();
  let utNom = cas ? cas.nom : ''; utNom = utNom.replace(/^UT\s+/i,'').trim();
  const caserneNom = cas ? cas.nom : '';
  const saved = _autorisationData[ivId] || {};
  const type = saved.demandeurType || 'Propri\u00e9taire';
  const autreTexte = saved.autreTexte || '';
  const nomComplet = ((saved.prenom||'')+' '+(saved.nom||'')).trim();
  const adresse = saved.adresse||''; const commune = saved.commune||'';
  const dateFr = saved.date ? saved.date.split('-').reverse().join('/') : '';
  const sigDateFr = saved.sigDate ? saved.sigDate.split('-').reverse().join('/') : dateFr;
  const sigLieu = saved.sigLieu||commune;
  const objet = saved.objet||''; const nature = saved.nature||'';
  const travaux = saved.travaux||[];
  const travauxAutreChk = saved.travauxAutreChk||false;
  const travauxAutreTxt = saved.travauxAutreTxt||'';
  const sigDataUrl = saved.signature||null;

  const TFORM=['D\u00e9pose d\u2019une antenne','D\u00e9montage de t\u00f4les','D\u00e9pose de tuiles','D\u00e9coupe d\u2019un panneau','R\u00e9alisation d\u2019une trou\u00e9e dans un mur ou une chemin\u00e9e'];
  const TLBL=['La d\u00e9pose d\u2019une antenne','Le d\u00e9montage de t\u00f4les','La d\u00e9pose de tuiles','La d\u00e9coupe d\u2019un panneau','La r\u00e9alisation d\u2019une trou\u00e9e dans un mur ou une chemin\u00e9e'];

  function st(txt,strike){return strike?'<span style="text-decoration:line-through;color:#aaa;">'+txt+'</span>':txt;}

  const allItems=TLBL.slice();
  if(travauxAutreChk&&travauxAutreTxt)allItems.push('Autre\u00a0: '+travauxAutreTxt);
  const pc=Math.ceil(allItems.length/3);
  const cols=[allItems.slice(0,pc),allItems.slice(pc,pc*2),allItems.slice(pc*2)];
  const trHtml='<table style="width:100%;border:none;margin:6px 0;"><tr>'+cols.map(function(col){
    return '<td style="width:33%;vertical-align:top;border:none;padding:0 4px 0 0;"><ul style="margin:0;padding-left:14px;">'+col.map(function(lbl){
      const fi=TLBL.indexOf(lbl);
      const ok=fi>=0?travaux.includes(TFORM[fi]):(travauxAutreChk&&!!travauxAutreTxt);
      return '<li style="margin:3px 0;font-size:10pt;'+(ok?'':'text-decoration:line-through;color:#999;')+'">'+lbl+'</li>';
    }).join('')+'</ul></td>';
  }).join('')+'</tr></table>';

  const trCoches=TLBL.filter(function(l,i){return travaux.includes(TFORM[i]);});
  if(travauxAutreChk&&travauxAutreTxt)trCoches.push('Autre\u00a0: '+travauxAutreTxt);

  const prop17='La remise en \u00e9tat des \u00e9l\u00e9ments d\u00e9plac\u00e9s ou endommag\u00e9s reste \u00e0 la charge du '
    +'<strong>'+st('PROPRI\u00c9TAIRE',type!=='Propri\u00e9taire')+'</strong> ou du '
    +'<strong>'+st('LOCATAIRE.',type!=='Locataire')+'</strong>';

  const sigImg=sigDataUrl
    ?'<img src="'+sigDataUrl+'" style="height:55px;max-width:200px;display:block;margin-top:4px;">'
    :'<div style="height:55px;border-bottom:1px solid #000;width:200px;margin-top:4px;"></div>';

  const logoSrc=_getLogoSrc();
  const css='<style>@page{size:210mm 148mm;margin:0;}'
    +'*{box-sizing:border-box;}'
    +'body{font-family:Calibri,Arial,sans-serif;font-size:10pt;color:#000;margin:0;padding:20px 0;background:#e0e0e0;}'
    +'.page{width:210mm;min-height:148mm;margin:0 auto 20px auto;padding:10mm;background:#fff;box-shadow:0 2px 12px rgba(0,0,0,.25);page-break-after:always;}'
    +'.page:last-child{page-break-after:auto;}'
    +'.hdr{position:relative;display:flex;align-items:center;margin-bottom:6px;min-height:42px;}'
    +'.hdr img{position:absolute;left:0;top:0;height:15mm;max-width:60mm;width:auto;object-fit:contain;}'
    +'.hdr-r{width:100%;text-align:center;}'
    +'.hdr-r .ut-sub{font-size:12pt;}'
    +'.hdr-r .utn{font-size:14pt;font-weight:bold;}'
    +'h2{text-align:center;font-size:14pt;font-weight:bold;text-decoration:underline;margin:4px 0 6px 0;}'
    +'p{margin:0;line-height:1.5;font-size:10pt;}'
    +'.sig-t{width:100%;border-collapse:collapse;margin-top:6px;}'
    +'.sig-t td{border:1px solid #000;padding:5px 6px;vertical-align:top;width:50%;font-size:10pt;}'
    +'.np{position:fixed;top:10px;right:10px;z-index:999;background:#fff;padding:8px;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,.2);display:flex;gap:6px;flex-wrap:wrap;}'
    +'.np button{padding:6px 12px;border:none;border-radius:5px;cursor:pointer;font-size:12px;}'
    +'@media print{.np{display:none;}body{background:none;padding:0;}.page{width:100%;min-height:auto;margin:0;padding:10mm;box-shadow:none;}}</style>';

  const hdr='<div class="hdr"><img src="'+logoSrc+'" alt="Logo">'
    +'<div class="hdr-r">'
    +'<div class="ut-sub">Unit\u00e9 territoriale de</div>'
    +'<div class="utn">'+utNom+'</div>'
    +'</div></div>';

  const dLine='A la demande de (Nom du '
    +st('propri\u00e9taire',type!=='Propri\u00e9taire')+', '
    +st('du locataire',type!=='Locataire')+', '
    +st('autre',type!=='Autre')
    +')\u00a0: <strong>'+nomComplet+(type==='Autre'?' ('+autreTexte+')':'')+'</strong>';

  const sigTbl='<table class="sig-t"><tr>'
    +'<td><strong>Noms des intervenants</strong><br><br>'+caserneNom+'</td>'
    +'<td><strong>ACCORD DU PROPRI\u00c9TAIRE OU LOCATAIRE</strong><br><br>'
    +'Fait le\u00a0: <strong>'+sigDateFr+'</strong>'+(sigLieu?'\u00a0\u00e0\u00a0<strong>'+sigLieu+'</strong>':'')
    +'<br><br>Signature\u00a0:<br>'+sigImg+'</td></tr></table>';

  const pAuto='<div class="page">'+hdr
    +'<h2>AUTORISATION D\u2019INTERVENTION</h2>'
    +'<p>'+dLine+'</p>'
    +'<p>Les sapeurs-pompiers se sont pr\u00e9sent\u00e9s au\u00a0<em>(adresse)</em>\u00a0: <strong>'+adresse+'</strong></p>'
    +'<p>Commune\u00a0<strong>'+commune+'</strong>, \u00e0 la date du\u00a0: <strong>'+dateFr+'</strong></p>'
    +'<p>Pour\u00a0<em>(objet de l\u2019intervention)</em>\u00a0: <strong>'+objet+'</strong></p>'
    +'<p>Lors de cette intervention a \u00e9t\u00e9 r\u00e9alis\u00e9\u00a0<em>(nature de l\u2019intervention)</em>\u00a0: <strong>'+nature+'</strong></p>'
    +'<p><strong>Avant le d\u00e9but de l\u2019intervention</strong>, le '
    +st('propri\u00e9taire',type==='Locataire'||type==='Autre')+', le '
    +st('locataire',type==='Propri\u00e9taire'||type==='Autre')
    +' ou autre a \u00e9t\u00e9 inform\u00e9 express\u00e9ment que la r\u00e9alisation de celle-ci n\u00e9cessite<sup>(1)</sup>\u00a0:</p>'
    +trHtml
    +'<p>'+prop17+'</p>'
    +sigTbl
    +'<p style="font-size:8pt;color:#888;"><sup>(1)</sup> Rayer les mentions inutiles</p>'
    +'</div>';

  const trCochTxt=trCoches.length?'<br>Travaux r\u00e9alis\u00e9s\u00a0: <strong>'+trCoches.join(', ')+'</strong>.':'';
  const pAttest='<div class="page">'+hdr
    +'<h2>ATTESTATION D\u2019INTERVENTION</h2>'
    +'<p>Suite \u00e0 la demande d\u2019intervention du '
    +st('propri\u00e9taire',type!=='Propri\u00e9taire')+', du '
    +st('locataire',type!=='Locataire')+', '+st('autre',type!=='Autre')+'\u00a0: '
    +'<strong>'+nomComplet+(type==='Autre'?' ('+autreTexte+')':'')+'</strong></p>'
    +'<p>Nous soussign\u00e9s, la Communaut\u00e9 d\u2019Agglom\u00e9ration B\u00e9thune-Bruay, Artois Lys Romane, certifions que l\u2019unit\u00e9 territoriale de <strong>'+utNom+'</strong>, appartenant au Corps Communautaire, est intervenue au\u00a0: <strong>'+adresse+'</strong></p>'
    +'<p>Commune\u00a0<strong>'+commune+'</strong>, \u00e0 la date du\u00a0: <strong>'+dateFr+'</strong></p>'
    +'<p>Pour\u00a0<em>(objet de l\u2019intervention)</em>\u00a0: <strong>'+objet+'</strong></p>'
    +'<p>Lors de cette intervention, a \u00e9t\u00e9 r\u00e9alis\u00e9\u00a0: <strong>'+nature+'</strong>'+trCochTxt+'</p>'
    +'<p>'+prop17+'</p>'
    +sigTbl
    +'<p style="font-size:8pt;color:#888;"><sup>(1)</sup> Rayer les mentions inutiles</p>'
    +'</div>';

  const showA=!docType||docType==='autorisation';
  const showT=!docType||docType==='attestation';
  let body='';
  if(showA)body+=pAuto;
  if(showT)body+=pAttest;

  const ttl=docType==='autorisation'?'Autorisation':docType==='attestation'?'Attestation':'Autorisation & Attestation';
  const npBtns=(!docType)
    ?'<button onclick="previewAutorisationPDF(\'_IVID_\',\'autorisation\')" style="background:#185FA5;color:#fff;">&#x1F4CB; Autorisation seule</button>'
     +'<button onclick="previewAutorisationPDF(\'_IVID_\',\'attestation\')" style="background:#3B6D11;color:#fff;">&#x1F4CB; Attestation seule</button>'
    :'';
  const html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>'+ttl+'</title>'+css+'</head><body>'
    +'<div class="np">'
    +'<button onclick="window.print()" style="background:#C0392B;color:#fff;">&#x1F5A8; Imprimer / PDF</button>'
    +npBtns.replace(/_IVID_/g, ivId)
    
    +'</div>'+body+'</body></html>';

  openIframeModal(html);
}

function genAutorisationDocx(ivId) {
  saveAutorisationData(ivId);
  const iv = IVS.find(function(v){return v.id===ivId;});if(!iv)return;
  const cas = CC();
  let utNom = cas ? cas.nom : ''; utNom = utNom.replace(/^UT\s+/i,'').trim();
  const caserneNom = cas ? cas.nom : '';
  const saved = _autorisationData[ivId] || {};
  const type = saved.demandeurType || 'Propri\u00e9taire';
  const nomComplet = ((saved.prenom||'')+' '+(saved.nom||'')).trim();
  const adresse = saved.adresse||''; const commune = saved.commune||'';
  const dateFr = saved.date ? saved.date.split('-').reverse().join('/') : '';
  const sigDateFr = saved.sigDate ? saved.sigDate.split('-').reverse().join('/') : dateFr;
  const sigLieu = saved.sigLieu||commune;
  const objet = saved.objet||''; const nature = saved.nature||'';
  const travaux = saved.travaux||[];
  const travauxAutreChk = saved.travauxAutreChk||false;
  const travauxAutreTxt = saved.travauxAutreTxt||'';
  const sigDataUrl = saved.signature||null;

  const TLBL=['La d\u00e9pose d\u2019une antenne','Le d\u00e9montage de t\u00f4les','La d\u00e9pose de tuiles','La d\u00e9coupe d\u2019un panneau','La r\u00e9alisation d\u2019une trou\u00e9e dans un mur ou une chemin\u00e9e'];
  const TFORM=['D\u00e9pose d\u2019une antenne','D\u00e9montage de t\u00f4les','D\u00e9pose de tuiles','D\u00e9coupe d\u2019un panneau','R\u00e9alisation d\u2019une trou\u00e9e dans un mur ou une chemin\u00e9e'];

  function ex(s){return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function addStrike(xml,text){
    const esc=text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    return xml.replace(new RegExp('(<w:r(?:\\s[^>]*)?>)(<w:rPr>)((?:(?!<\\/w:rPr>).)*)(<\\/w:rPr>)(<w:t(?:[^>]*)?>'+esc+'<\\/w:t><\\/w:r>)'),function(m,r,ro,rc,rc2,run){if(rc.includes('<w:strike'))return m;return r+ro+rc+'<w:strike/>'+rc2+run;});
  }

  function doGen(){
    const JSZip=window.JSZip;
    const binStr=atob(AUTORISATION_DOCX_B64);
    const bytes=new Uint8Array(binStr.length);
    for(let i=0;i<binStr.length;i++)bytes[i]=binStr.charCodeAt(i);
    JSZip.loadAsync(bytes.buffer).then(function(zip){
      return zip.file('word/header1.xml').async('string').then(function(hdr){
        // Header: "L" + "apugnoy" = two separate runs -> replace first with utNom, second with empty
        hdr=hdr.replace('<w:t>L</w:t></w:r>','<w:t>'+ex(utNom)+'</w:t></w:r>');
        hdr=hdr.replace('<w:t>apugnoy</w:t></w:r>','<w:t></w:t></w:r>');
        zip.file('word/header1.xml',hdr);
      }).then(function(){return zip.file('word/document.xml').async('string');}).then(function(doc){

        // === AUTORISATION ===

        // P02: Demandeur type - biff les types non sélectionnés
        // Runs: "du propriétaire" / "du locataire" / "autre "
        if(type!=='Propriétaire') doc=addStrike(doc,'du propriétaire');
        if(type!=='Locataire') doc=addStrike(doc,'du locataire');
        if(type!=='Autre') doc=addStrike(doc,'autre ');
        // P02: Remplir le nom après ") : ___"
        // Le run contient " : _" puis d'autres runs avec "_..."
        // On remplace le premier run underscore et supprime les suivants
        var nomValeur = ex(nomComplet + (type === 'Autre' && autreTexte ? ' (' + autreTexte + ')' : ''));
        doc=doc.replace(
          /(<w:t>) : _(<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)*/s,
          '$1 : '+nomValeur+'$2'
        );

        // P03: Adresse - après "(adresse)   : " il y a des runs d'underscores
        // Pattern: <w:t>: </w:t></w:r> puis underscore runs
        doc=doc.replace(
          /(<w:t xml:space="preserve">: <\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '$1<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>'+ex(adresse)+'</w:t></w:r>'
        );

        // P04: Commune - après "<w:t>Commune</w:t>" il y a des runs d'underscores
        doc=doc.replace(
          /(<w:t>Commune<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '$1<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t xml:space="preserve"> '+ex(commune)+'</w:t></w:r>'
        );
        // P04: Date - run "à la date du : ______..."
        doc=doc.replace(
          /<w:t>à la date du : ______<\/w:t><\/w:r><w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>/s,
          '<w:t>à la date du : '+ex(dateFr)+'</w:t></w:r>'
        );

        // P05: Objet - run ": _______________" puis autres runs underscores
        doc=doc.replace(
          /(<w:t>: _______________<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>: '+ex(objet)+'</w:t></w:r>'
        );

        // P06: Nature - run " : __________" puis autres runs underscores
        doc=doc.replace(
          /(<w:t> : __________<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t> : '+ex(nature)+'</w:t></w:r>'
        );

        // P10-P14: Travaux - biffer les items non cochés
        // Textes exacts des runs:
        var travLabel0='d’pose d’une antenne';// "La " + "dépose d'une antenne"
        var travTexts=[
          'dépose d’une antenne',
          'Le démontage de tôles',
          'La dépose de tuiles',
          'La découpe d’un panneau',
          'La réalisation d’une trouée dans un mur ou une cheminée'
        ];
        if(!travaux.includes(TFORM[0])) doc=addStrike(doc,'dépose d’une antenne');
        if(!travaux.includes(TFORM[1])) doc=addStrike(doc,'Le démontage de tôles');
        if(!travaux.includes(TFORM[2])) doc=addStrike(doc,'La dépose de tuiles');
        if(!travaux.includes(TFORM[3])) doc=addStrike(doc,'La découpe d’un panneau');
        if(!travaux.includes(TFORM[4])) doc=addStrike(doc,'La réalisation d’une trouée dans un mur ou une cheminée');
        if(!travauxAutreChk) doc=addStrike(doc,'Autre (préciser)');

        // P17: PROPRIÉTAIRE/LOCATAIRE - biffer celui qui ne correspond pas
        if(type!=='Propriétaire') doc=addStrike(doc,'PROPRIÉTAIRE');
        if(type!=='Locataire') doc=addStrike(doc,'LOCATAIRE.');

        // Table Noms des intervenants - remplir la cellule vide sous "Noms des intervenants"
        doc=doc.replace(
          /(Noms des intervenants<\/w:t>.*?<\/w:tc>\s*<w:tc>.*?<w:p[^>]*>)(\s*<w:pPr>.*?<\/w:pPr>\s*)(<\/w:p>)/s,
          function(m,b,p,e){return b+p+'<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>'+ex(caserneNom)+'</w:t></w:r>'+e;}
        );

        // P23: "Le :" -> date + lieu signature (autorisation)
        doc=doc.replace('<w:t>Le :</w:t></w:r>',
          '<w:t xml:space="preserve">Le : '+ex(sigDateFr)+(sigLieu?' à '+ex(sigLieu):'')+' </w:t></w:r>'
        );

        // === ATTESTATION ===

        // P31: biff demandeur type
        if(type!=='Propriétaire') doc=addStrike(doc,'propriétaire');
        if(type!=='Locataire') doc=addStrike(doc,'locataire');
        // P31: remplir le nom après "autre (1) :"
        doc=doc.replace(
          /(<w:t> :<\/w:t><\/w:r><w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t xml:space="preserve"> <\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '$1<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>'+ex(nomComplet)+'</w:t></w:r>'
        );

        // P32: Remplacer "erritoriale de L" + "apugnoy" runs
        doc=doc.replace('<w:t>erritoriale de L</w:t></w:r>',
          '<w:t>erritoriale de '+ex(utNom)+'</w:t></w:r>'
        );
        doc=doc.replace('<w:t>apugnoy</w:t></w:r>','<w:t></w:t></w:r>');
        // P32: adresse après "(adresse) :"
        // Run: " :" suivi de underscores
        doc=doc.replace(
          /(<w:t> :<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>[_ ]*<\/w:t><\/w:r>)+/s,
          '$1<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t> '+ex(adresse)+'</w:t></w:r>'
        );

        // P33: Commune + date (un seul run avec tout)
        doc=doc.replace(
          'Commune________________________________________________, à la date du : _______________________________________',
          'Commune '+ex(commune)+', à la date du : '+ex(dateFr)
        );

        // P34: Objet attestation - après "(objet de l'intervention) " il y a underscores
        doc=doc.replace(
          /(<w:t>\(objet de l’intervention\) <\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '$1<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>'+ex(objet)+'</w:t></w:r>'
        );

        // P36: Nature attestation - " : _______..." runs
        doc=doc.replace(
          /(<w:t> : _______________________________________<\/w:t><\/w:r>)(<w:r[^>]*><w:rPr>.*?<\/w:rPr><w:t[^>]*>_+<\/w:t><\/w:r>)+/s,
          '<w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t> : '+ex(nature)+'</w:t></w:r>'
        );
        // Fallback si pas de run supplémentaire
        doc=doc.replace('<w:t> : _______________________________________</w:t></w:r>',
          '<w:t> : '+ex(nature)+'</w:t></w:r>'
        );

        // P38: PROPRIÉTAIRE/LOCATAIRE attestation
        if(type!=='Propriétaire') doc=addStrike(doc,'PROPRIÉTAIRE');
        if(type!=='Locataire') doc=addStrike(doc,'LOCATAIRE.');

        // P43: "Le :" signature attestation (même tag, deuxième occurrence après P23)
        // Déjà traité par le premier replace (remplace toutes les occurrences)

        zip.file('word/document.xml',doc);
        if(sigDataUrl){
          zip.file('word/media/signature.png',sigDataUrl.split(',')[1],{base64:true});
          return zip.file('word/_rels/document.xml.rels').async('string').then(function(rels){
            if(!rels.includes('signature.png'))rels=rels.replace('</Relationships>','<Relationship Id="rId99" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/signature.png"/>\n</Relationships>');
            zip.file('word/_rels/document.xml.rels',rels);return zip;
          });
        }
        return zip;
      }).then(function(z){return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}).then(function(blob){
        const a=document.createElement('a');a.href=URL.createObjectURL(blob);
        a.download='Autorisation_'+iv.id+'_'+dateFr.replace(/\//g,'-')+'.docx';a.click();
        showToast('Document téléchargé','success');
      });
    });
  }
  if(window.JSZip){doGen();}
  else{
    showToast('Chargement...','info');
    const s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
    s.onload=doGen;s.onerror=function(){showToast('Erreur JSZip','error');};
    document.head.appendChild(s);
  }
}

function editAdresse(ivId){
  const iv=IVS.find(v=>v.id===ivId);if(!iv)return;
  document.getElementById('mt').textContent='Corriger l’adresse';
  document.getElementById('mi').textContent=iv.id;
  document.getElementById('mb').innerHTML=`
    <div>
      <div class="fg"><div class="fgl">Adresse</div>
        <input class="fi" type="text" id="edit-addr-val" value="${escHtml(iv.addr||'')}" placeholder="ex. 12 rue des Lilas"/>
      </div>
      <div class="fg"><div class="fgl">Complement d’adresse</div>
        <input class="fi" type="text" id="edit-addr-comp" value="${escHtml(iv.addrComp||'')}" placeholder="Bât. B, apt. 12…"/>
      </div>
      <div id="edit-addr-err" style="font-size:12px;color:#E24B4A;display:none;margin-bottom:8px;"></div>
      <div class="brow">
        <button class="btn pr sm" onclick="saveAdresse('${ivId}')">&#x1F4BE; Enregistrer</button>
        <button class="btn sm" onclick="oM('${ivId}')">Retour</button>
      </div>
    </div>`;
  document.getElementById('mo').style.display='flex';
}
function saveAdresse(ivId){
  const iv=IVS.find(v=>v.id===ivId);if(!iv)return;
  const addr=document.getElementById('edit-addr-val').value.trim();
  const comp=document.getElementById('edit-addr-comp').value.trim();
  const err=document.getElementById('edit-addr-err');
  if(!addr){err.style.display='block';err.textContent='L’adresse est obligatoire.';return;}
  const notes=[];
  if((iv.addr||'')!==addr)notes.push('Adresse : '+(iv.addr||'—')+' → '+addr);
  if((iv.addrComp||'')!==comp)notes.push('Compl. adresse : '+(iv.addrComp||'—')+' → '+(comp||'—'));
  iv.addr=addr;
  iv.addrComp=comp;
  pushTL(iv,'modif-adresse',CU.l);
  if(notes.length)iv.tl[iv.tl.length-1].note=notes.join(' ; ');
  if(typeof _jbEditLock!=='undefined')_jbEditLock=Date.now();
  saveData(true); // push immédiat : sinon la correction est écrasée au prochain pull
  cM();rI();oM(ivId);
}

